// === Engagement Refresh (daily) ===
// Posts scraped on Thursday carry a 0-7 day-old engagement snapshot. This job runs DAILY and,
// for ATTRIBUTED LinkedIn posts crossing 7 days of age (posted_at in [now-8d, now-7d)),
// re-scrapes CURRENT engagement via apimaestro/linkedin-post-detail (accepts bare activity ids,
// ~$0.005/post), updates totalReactions/comments/reshares, and recomputes post_weight with the
// ternary author model (company B1/M1, employee B2/M1.2, external B5/M2; sentiment NULL -> 1.0).
// Each post is finalized exactly once, after its first full week. Batches of 20 ids per Apify call.
const helpers = this.helpers;
const KEY = '<REDACTED_SUPABASE_JWT>';
const BASE = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const APIFY_TOKEN = '<REDACTED_APIFY_TOKEN>';
const ACTOR = 'apimaestro~linkedin-post-detail';

// Model inputs (config + URN set + employee cache) — self-contained, no creds to bind.
const cfgRows = await helpers.httpRequest({ method: 'GET', url: BASE + '/sov_config?select=config&id=eq.1', headers: H, json: true });
const cfg = (cfgRows && cfgRows[0] && cfgRows[0].config) || {};
const comps = await helpers.httpRequest({ method: 'GET', url: BASE + '/competitors?select=name,linkedin_urn&active=eq.true', headers: H, json: true });
const urnSet = new Set((comps || []).map(c => String(c.linkedin_urn || '')).filter(Boolean));
const EMP = {};
try { const aff = await helpers.httpRequest({ method: 'GET', url: BASE + '/author_affiliation?select=profile_id,competitor&verdict=eq.employee', headers: H, json: true }); for (const a of (aff || [])) { if (a && a.profile_id && a.competitor) EMP[String(a.competitor).trim().toLowerCase() + '|' + String(a.profile_id)] = true; } } catch (e) {}
const clamp = cfg.sentimentClamp || { min: 0.5, max: 1.3 };
const lw = (cfg.engagementWeights || {}).LinkedIn || { reaction: 1, comment: 3, reshare: 10, image: 1.5 };
const AB = cfg.authorBaseline || { company: 1.0, employee: 2.0, external: 5.0 };
const AEM = cfg.authorEngMult || { company: 1.0, employee: 1.2, external: 2.0 };
const hlLI = (cfg.halfLifeDays || {}).LinkedIn || 14;

function num(x, d) { return (x != null ? Number(x) : d); }
function round6(x) { return parseFloat(Number(x).toFixed(6)); }
function sentMult(x) { if (x == null) return 1.0; const s = Math.max(-3, Math.min(3, Number(x))); return clamp.min + ((s + 3) / 6) * (clamp.max - clamp.min); }
function ageDays(t) { if (!t) return 0; const d = new Date(t); return isNaN(d) ? 0 : Math.max(0, (Date.now() - d.getTime()) / 86400000); }
function decay(age, hl) { return age <= 7 ? 1 : Math.pow(2, -age / hl); }
function authorTier(r) { const a = (r.author && typeof r.author === 'object') ? r.author : {}; const prof = String(a.profile_id || ''); const head = String(a.headline || '').toLowerCase(); const cn = String(r.companyName || ''); if (prof && urnSet.has(prof)) return 'company'; if (prof && cn && cn !== 'NONE' && EMP[cn.toLowerCase() + '|' + prof]) return 'employee'; if (cn && cn !== 'NONE' && head.indexOf(cn.toLowerCase()) !== -1) return 'employee'; return 'external'; }
function tierB(t) { return t === 'company' ? num(AB.company, 1.0) : (t === 'employee' ? num(AB.employee, 2.0) : num(AB.external, 5.0)); }
function tierM(t) { return t === 'company' ? num(AEM.company, 1.0) : (t === 'employee' ? num(AEM.employee, 1.2) : num(AEM.external, 2.0)); }

// Window: attributed posts that crossed 7 days old since yesterday's run.
const now = Date.now();
const from = new Date(now - 8 * 86400000).toISOString();
const to = new Date(now - 7 * 86400000).toISOString();
const rows = await helpers.httpRequest({ method: 'GET', url: BASE + '/linkedin_posts?select=activity_id,companyName,sentiment,posted_at,author,imageURL,has_video&companyName=not.is.null&companyName=neq.NONE&posted_at=gte.' + encodeURIComponent(from) + '&posted_at=lt.' + encodeURIComponent(to) + '&order=activity_id&limit=200', headers: H, json: true });
const list = Array.isArray(rows) ? rows : [];
if (!list.length) return [{ json: { engagementRefresh: true, window: [from, to], found: 0, scraped: 0, updated: 0 } }];
const byId = {}; for (const r of list) byId[String(r.activity_id)] = r;

let scraped = 0, updated = 0; const failed = [];
for (let i = 0; i < list.length; i += 20) {
  const chunk = list.slice(i, i + 20).map(r => String(r.activity_id));
  let items = [];
  try {
    items = await helpers.httpRequest({ method: 'POST', url: 'https://api.apify.com/v2/acts/' + ACTOR + '/run-sync-get-dataset-items?token=' + APIFY_TOKEN, headers: { 'Content-Type': 'application/json' }, body: { post_urls: chunk }, json: true, timeout: 240000 });
  } catch (e) { failed.push.apply(failed, chunk); continue; }
  for (const it of (Array.isArray(items) ? items : [])) {
    const pid = String((it.post && it.post.id) || it.input || '');
    const row = byId[pid]; if (!row) continue;
    const st = it.stats || {};
    if (st.total_reactions == null && st.comments == null && st.shares == null) continue; // dead/deleted post -> keep old values
    scraped++;
    const tr = Number(st.total_reactions || 0), cm = Number(st.comments || 0), sh = Number(st.shares || 0);
    let eng = num(lw.reaction, 1) * tr + num(lw.comment, 3) * cm + num(lw.reshare, 10) * sh;
    if (row.imageURL && String(row.imageURL).length > 0) eng += num(lw.image, 1.5);
    if (row.has_video) eng += num(lw.video, 2);
    const t = authorTier(row);
    const pw = round6((tierB(t) + Math.pow(Math.max(0, eng), 49 / 50) * tierM(t)) * sentMult(row.sentiment) * decay(ageDays(row.posted_at), hlLI));
    try {
      await helpers.httpRequest({ method: 'PATCH', url: BASE + '/linkedin_posts?activity_id=eq.' + encodeURIComponent(pid), headers: Object.assign({}, H, { 'Content-Type': 'application/json', Prefer: 'return=minimal' }), body: { totalReactions: tr, comments: cm, reshares: sh, post_weight: pw }, json: true });
      updated++;
    } catch (e) { failed.push(pid); }
  }
}
return [{ json: { engagementRefresh: true, window: [from, to], found: list.length, scraped: scraped, updated: updated, failed: failed } }];
